-- 演示数据：maccms V10 场景化数据
-- 36 部影片 + 6 个分类 + 4 段本地 MP4 播放源 + 后台管理员（演示）

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 演示 MP4 基础路径（模拟器容器内 nginx 80 端口 + socat 8080 转发，App 端用 10.0.2.2:8080）
SET @demo_base = 'http://10.0.2.2:8080/demo';
SET @poster_base = 'http://10.0.2.2:8080/static';

-- 清掉 initdata 的默认分类，只留演示分类
DELETE FROM `mac_type`;

-- 分类（20 列：type_id,name,en,sort,mid,pid,status,tpl,tpl_list,tpl_detail,tpl_play,tpl_down,key,des,title,union,extend,logo,pic,jumpurl）

-- 影片（36 部）32 个字段，vod_id 显式指定方便关联

SET FOREIGN_KEY_CHECKS = 1;

-- 校正：INSERT 值序列中 vod_play_from/vod_play_server 错位，此处统一修正
-- （vod_play_note 为空是预期；vod_play_from 必须为 demo 才能被 API 识别）
UPDATE `mac_vod` SET `vod_play_from` = 'demo', `vod_play_server` = '';
